@startuml

class GasStation {
  + location : string
}

class Pump {
  + currentLevel : float
  + reorderingLevel : float
  + criticalLevel : float
  + isBlocked : boolean
}

class GasolineType {
  + name : string
}

class Reservoir {
  + currentLevel : float
  + reorderingLevel : float
  + criticalLevel : float
}

class RefuelTurn {
  + amount : float
  + date : date
}

class Customer {
  + name : string
  + isSuspended : boolean
  + isBlocked : boolean
  + slackThreshold : int
}

class RefuelCard {
  + cardNumber : string
}

class Invoice {
  + month : int
  + year : int
  + discount : float
}

class Payment {
  + amount : float
  + date : date
}

class DailyReport {
  + date : date
}

GasStation "1" *-- "*" Pump
Pump "1" -- "1" GasolineType
Pump "1" -- "1" Reservoir
Pump "1" -- "0..1" RefuelTurn : undergoes
Customer "1" -- "*" RefuelTurn : performs
Customer "1" -- "0..1" RefuelCard : holds
Customer "1" -- "*" Invoice : receives
Invoice "1" -- "*" RefuelTurn : contains
Invoice "1" -- "0..*" Payment : settled_by

@enduml

